  insert into public.notes (id, title, body, tags, pinned, owner_id, created_at, updated_at, deleted_at) values
    ('23eb6947-636f-5b60-91b6-fc02f6a87b11', 'Acme renewal call', $b$<h2>Summary</h2><p>Avery confirmed Acme wants to renew, but the quarterly billing option is a must.</p><h2>Discussion</h2><ul><li><p>Current seat count is 120, growing to 150 by January</p></li><li><p>Legal needs the updated DPA before signing</p></li><li><p>Decision expected by Friday</p></li></ul><h2>Next steps</h2><ul data-type="taskList"><li data-checked="true" data-type="taskItem"><p>Send the quarterly billing quote</p></li><li data-checked="false" data-type="taskItem"><p>Share the updated DPA</p></li><li data-checked="false" data-type="taskItem"><p>Book a check-in for Thursday</p></li></ul>$b$, array['call', 'renewal']::text[], true, pids[(4 % n) + 1], ((today - 6 + time '14:10:00') at time zone 'utc'), ((today + 0 + time '09:42:00') at time zone 'utc'), null),
    ('68264e38-4bfd-5200-aa85-097137df234f', 'Globex upsell: stakeholder map', $b$<h2>Who decides</h2><ul><li><p>Jonas Weber, VP Operations (sponsor)</p></li><li><p>Finance lead signs off above $40,000</p></li><li><p>IT only needs to review SSO</p></li></ul><h2>Risks</h2><p>The 12 month term is the sticking point. Offer a 6 month ramp with an option to extend.</p>$b$, array['meeting', 'strategy']::text[], true, pids[(8 % n) + 1], ((today - 9 + time '11:00:00') at time zone 'utc'), ((today - 1 + time '16:20:00') at time zone 'utc'), null),
    ('7f9bb4ff-677f-5f75-9685-9480374b292f', 'Pricing objections playbook', $b$<h2>Common objections</h2><ol><li><p>It is too expensive: anchor on time saved per rep</p></li><li><p>We already have a tool: show the migration plan</p></li><li><p>Not this quarter: offer a ramped start</p></li></ol><p>Review with the team on Monday.</p>$b$, array['idea', 'pricing']::text[], true, pids[(2 % n) + 1], ((today - 21 + time '10:30:00') at time zone 'utc'), ((today - 4 + time '13:05:00') at time zone 'utc'), null),
    ('34699635-6685-5906-b4cf-3b378086961a', 'Atlas Freight legal redlines', $b$<p>Grace sent back the MSA with redlines on liability and data retention.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><p>Ask legal to review clause 9</p></li><li data-checked="false" data-type="taskItem"><p>Confirm the 30 day data retention window</p></li><li data-checked="false" data-type="taskItem"><p>Reply to Grace by Wednesday</p></li></ul>$b$, array['follow-up', 'legal']::text[], false, pids[(13 % n) + 1], ((today - 5 + time '15:45:00') at time zone 'utc'), ((today + 0 + time '08:05:00') at time zone 'utc'), null),
    ('6dda0782-1afd-54fa-bd77-390c37d6da6f', 'Pinecrest security review prep', $b$<h2>Agenda</h2><ul><li><p>SOC 2 report walkthrough</p></li><li><p>Data residency options</p></li><li><p>Audit log retention</p></li></ul><p>Bring the HIPAA addendum. Dr. Reyes wants to see the breach notification process.</p>$b$, array['security', 'meeting']::text[], false, pids[(10 % n) + 1], ((today - 8 + time '09:15:00') at time zone 'utc'), ((today - 2 + time '17:30:00') at time zone 'utc'), null),
    ('0d77d92c-c105-5a94-8e1b-0bd326d6c157', 'Call with Ingrid Larsen', $b$<p>Verbal yes on the telemetry package. Waiting on procurement paperwork.</p><ul><li><p>PO expected within the week</p></li><li><p>Wants onsite training in November</p></li></ul>$b$, array['call']::text[], false, pids[(15 % n) + 1], ((today - 3 + time '10:20:00') at time zone 'utc'), ((today - 3 + time '10:55:00') at time zone 'utc'), null),
    ('a9af465b-f9ab-5e8d-83b5-536b29f57482', 'Lumen Retail rollout ideas', $b$<p>Start with 5 pilot stores, then roll out by region. A store manager dashboard could be the hook.</p><ul><li><p>Pilot: Northeast region</p></li><li><p>Success metric: weekly active managers</p></li><li><p>Training: 30 minute video</p></li></ul>$b$, array['idea']::text[], false, pids[(6 % n) + 1], ((today - 2 + time '12:00:00') at time zone 'utc'), ((today - 2 + time '12:40:00') at time zone 'utc'), null),
    ('a8d60a44-4d00-5165-aaa5-f861c3d4df6e', 'Meridian Bank sandbox terms', $b$<h2>Decisions</h2><ul><li><p>Sandbox runs for 60 days</p></li><li><p>No production data in the sandbox</p></li><li><p>Weekly check-in with Oliver</p></li></ul><h2>Action items</h2><ul data-type="taskList"><li data-checked="true" data-type="taskItem"><p>Send the sandbox agreement</p></li><li data-checked="false" data-type="taskItem"><p>Provision the test tenant</p></li></ul>$b$, array['meeting', 'legal']::text[], false, pids[(16 % n) + 1], ((today - 2 + time '15:00:00') at time zone 'utc'), ((today - 1 + time '09:10:00') at time zone 'utc'), null),
    ('fd273168-6b91-58a0-89da-00ef329f44ab', 'Quarterly pipeline review', $b$<p>Pipeline coverage is 3.1x for Q4. Proposal stage is the bottleneck.</p><ul><li><p>Add a proposal template with pricing tiers</p></li><li><p>Shorten legal review with pre-approved clauses</p></li><li><p>Target 20% more demos in November</p></li></ul>$b$, array['meeting', 'strategy']::text[], false, pids[(8 % n) + 1], ((today - 13 + time '16:00:00') at time zone 'utc'), ((today - 13 + time '16:50:00') at time zone 'utc'), null),
    ('a74e89cd-2153-50e8-bfdc-599156250cb0', 'Avery Brooks intro notes', $b$<p>Avery runs procurement at Acme. Prefers short emails and a single point of contact.</p><ul><li><p>Timezone: US Central</p></li><li><p>Best time to call: mornings</p></li><li><p>Reports to the COO</p></li></ul>$b$, array['call', 'onboarding']::text[], false, pids[(4 % n) + 1], ((today - 19 + time '11:30:00') at time zone 'utc'), ((today - 12 + time '14:00:00') at time zone 'utc'), null),
    ('8687adb9-69f7-5521-8716-6f594f223ec9', 'Webinar follow-up list', $b$<ul data-type="taskList"><li data-checked="true" data-type="taskItem"><p>Email the 14 attendees with the recording</p></li><li data-checked="true" data-type="taskItem"><p>Tag hot leads in the CRM</p></li><li data-checked="false" data-type="taskItem"><p>Book 3 demos from the Q&A</p></li></ul><p>Attendance was higher than expected. Run the next one with a customer speaker.</p>$b$, array['follow-up', 'idea']::text[], false, pids[(10 % n) + 1], ((today - 15 + time '09:00:00') at time zone 'utc'), ((today - 11 + time '17:15:00') at time zone 'utc'), null),
    ('50a728ae-599a-55c9-9a83-9dbfa9d29d9f', 'Pinecrest Health account plan', $b$<h2>Goals for the year</h2><ol><li><p>Land the platform deal</p></li><li><p>Expand to two more clinics</p></li><li><p>Reference customer by Q3</p></li></ol><p>Executive sponsor: Dr. Alma Reyes.</p>$b$, array['strategy']::text[], false, pids[(11 % n) + 1], ((today - 25 + time '13:20:00') at time zone 'utc'), ((today - 18 + time '10:10:00') at time zone 'utc'), null),
    ('51c7d717-d777-5db4-83c6-2339452211ad', 'Cobalt Marine objections', $b$<p>Ingrid thinks the hardware add-on is overpriced. We can bundle sensors at cost if they commit to two years.</p><ul><li><p>Offer: sensors at cost</p></li><li><p>Condition: 24 month term</p></li><li><p>Approval needed from finance</p></li></ul>$b$, array['pricing', 'call']::text[], false, pids[(15 % n) + 1], ((today - 26 + time '14:40:00') at time zone 'utc'), ((today - 22 + time '11:25:00') at time zone 'utc'), null),
    ('8b7ee727-7d22-5e3b-b73a-86815f18d13e', 'Onboarding checklist draft', $b$<p>A shared checklist for new customers in the first 30 days.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><p>Kickoff call within 3 days</p></li><li data-checked="false" data-type="taskItem"><p>Admin training session</p></li><li data-checked="false" data-type="taskItem"><p>First report delivered by day 14</p></li><li data-checked="false" data-type="taskItem"><p>30 day review</p></li></ul>$b$, array['idea', 'onboarding']::text[], false, pids[(13 % n) + 1], ((today - 33 + time '10:00:00') at time zone 'utc'), ((today - 30 + time '15:30:00') at time zone 'utc'), null)
