-- =====================================================================================================================
-- Pivora CRM demo data. Run in the Supabase SQL Editor AFTER both migrations and AFTER creating the test accounts.
--
-- Loads the same demo data the app has today: 62 contacts, 24 deals, 14 notes, 45 calendar events, 8 projects with their tasks,
-- the activity timelines and the links between records. Everything is dated relative to the fixed demo "today" (2025-10-20), so the
-- Dashboard, overdue flags and "days in stage" look exactly as they do now.
--
-- Ownership is spread evenly over the profiles that exist (read from the profiles table, so it works with any number of accounts):
-- contacts go round-robin, and a deal, its contact, and the notes, events and projects linked to them belong to the same person.
--
-- Safe to run again: every row has a fixed id and is inserted with "on conflict (id) do update", so running it twice gives the same
-- data (and puts the demo rows back to how they are in this file). Rows you created yourself are not touched.
-- Run it as the postgres role (the SQL Editor default), which bypasses row level security.
-- =====================================================================================================================
do $seed$
declare
  today constant date := date '2025-10-20';
  pids uuid[];
  n int;
begin
  select array_agg(id order by created_at, id) into pids from public.profiles;
  n := coalesce(array_length(pids, 1), 0);
  if n = 0 then
    raise exception 'seed.sql: no profiles yet. Create your test accounts first (Authentication > Users), then run this file again.';
  end if;

  -- contacts
  on conflict (id) do update set name = excluded.name, email = excluded.email, phone = excluded.phone, company = excluded.company, job_title = excluded.job_title, status = excluded.status, source = excluded.source, owner_id = excluded.owner_id, tags = excluded.tags, last_contacted_at = excluded.last_contacted_at, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  -- deals
  on conflict (id) do update set title = excluded.title, company = excluded.company, contact_name = excluded.contact_name, contact_id = excluded.contact_id, value = excluded.value, stage = excluded.stage, priority = excluded.priority, owner_id = excluded.owner_id, close_date = excluded.close_date, stage_since = excluded.stage_since, next_step = excluded.next_step, notes = excluded.notes, lost_reason = excluded.lost_reason, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  -- notes
  on conflict (id) do update set title = excluded.title, body = excluded.body, tags = excluded.tags, pinned = excluded.pinned, owner_id = excluded.owner_id, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  -- calendar events
  on conflict (id) do update set title = excluded.title, type = excluded.type, start_at = excluded.start_at, end_at = excluded.end_at, all_day = excluded.all_day, platform = excluded.platform, location = excluded.location, attendees = excluded.attendees, description = excluded.description, status = excluded.status, owner_id = excluded.owner_id, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  -- projects
  on conflict (id) do update set name = excluded.name, description = excluded.description, status = excluded.status, owner_id = excluded.owner_id, member_ids = excluded.member_ids, due_date = excluded.due_date, archived_at = excluded.archived_at, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  -- tasks
  on conflict (id) do update set project_id = excluded.project_id, title = excluded.title, done = excluded.done, assignee_id = excluded.assignee_id, owner_id = excluded.owner_id, due_date = excluded.due_date, priority = excluded.priority, completed_at = excluded.completed_at, position = excluded.position, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  -- activity (the shared timeline)
  on conflict (id) do update set entity_type = excluded.entity_type, entity_id = excluded.entity_id, kind = excluded.kind, title = excluded.title, description = excluded.description, actor_id = excluded.actor_id, occurred_at = excluded.occurred_at, created_at = excluded.created_at, updated_at = excluded.updated_at;

  -- links ({ type, id } pairs; companies use target_key because they have no table)
  on conflict (id) do update set source_type = excluded.source_type, source_id = excluded.source_id, target_type = excluded.target_type, target_id = excluded.target_id, target_key = excluded.target_key, created_at = excluded.created_at, updated_at = excluded.updated_at, deleted_at = excluded.deleted_at;

  raise notice 'Pivora seed loaded: % contacts, % deals, % notes, % events, % projects, % tasks, % activity entries, % links across % profiles.',
    (select count(*) from public.contacts), (select count(*) from public.deals), (select count(*) from public.notes), (select count(*) from public.events),
    (select count(*) from public.projects), (select count(*) from public.tasks), (select count(*) from public.activity), (select count(*) from public.links), n;
end
$seed$;
